  {
    "ayat": "Pasal 16 ayat (1)",
    "isi": "Sepanjang tidak ditentukan lain oleh undang-undang tersendiri, setiap Penyelenggara Sistem Elektronik wajib mengoperasikan Sistem Elektronik yang memenuhi persyaratan minimum sebagai berikut: \na. dapat menampilkan kembali Informasi Elektronik dan/atau Dokumen Elektronik secara utuh sesuai dengan masa retensi yang ditetapkan dengan Peraturan Perundang-undangan; \nb. dapat melindungi ketersediaan, keutuhan, keotentikan, kerahasiaan, dan keteraksesan Informasi Elektronik dalam Penyelenggaraan Sistem Elektronik tersebut; \nc. dapat beroperasi sesuai dengan prosedur atau petunjuk dalam Penyelenggaraan Sistem Elektronik tersebut; \nd. dilengkapi dengan prosedur atau petunjuk yang diumumkan dengan bahasa, informasi, atau simbol yang dapat dipahami oleh pihak yang bersangkutan dengan Penyelenggaraan Sistem Elektronik tersebut; dan \ne. memiliki mekanisme yang berkelanjutan untuk menjaga kebaruan, kejelasan, dan kebertanggungjawaban prosedur atau petunjuk.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "pasal_ayat": "Pasal 16 ayat (2)",
    "isi": "Ketentuan lebih lanjut tentang Penyelenggaraan Sistem Elektronik sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Pemerintah.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 17 ayat (1)",
    "isi": "Penyelenggaraan Transaksi Elektronik dapat dilakukan dalam lingkup publik ataupun privat.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 17 ayat (2)",
    "isi": "Para pihak yang melakukan Transaksi Elektronik wajib beriktikad baik dalam melakukan interaksi dan/atau pertukaran Informasi Elektronik dan/atau Dokumen Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 17 ayat (3)",
    "perbuatan": "mengatur ketentuan lebih lanjut mengenai penyelenggaraan Transaksi Elektronik",
    "detail": "mengatur ketentuan lebih lanjut mengenai penyelenggaraan Transaksi Elektronik",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 18 ayat (1)",
    "isi": "Transaksi Elektronik yang dituangkan ke dalam Kontrak Elektronik mengikat para pihak.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 18 ayat (2)",
    "isi": "Para pihak memiliki kewenangan untuk memilih hukum yang berlaku bagi Transaksi Elektronik internasional yang dibuatnya.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 18 ayat (3)",
    "isi": "Jika para pihak tidak melakukan pilihan hukum dalam Transaksi Elektronik internasional, hukum yang berlaku didasarkan pada asas Hukum Perdata Internasional.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 18 ayat (4)",
    "isi": "Para pihak memiliki kewenangan untuk menetapkan forum pengadilan, arbitrase, atau lembaga penyelesaian sengketa alternatif lainnya yang berwenang menangani sengketa yang mungkin timbul dari Transaksi Elektronik internasional yang dibuatnya.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 18 ayat (5)",
    "isi": "Jika para pihak tidak melakukan pilihan forum sebagaimana dimaksud pada ayat (4), penetapan kewenangan pengadilan, arbitrase, atau lembaga penyelesaian sengketa alternatif lainnya yang berwenang menangani sengketa yang mungkin timbul dari transaksi tersebut, didasarkan pada asas Hukum Perdata Internasional.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 20 ayat (1)",
    "substansi": "Kecuali ditentukan lain oleh para pihak, Transaksi Elektronik terjadi pada saat penawaran transaksi yang dikirim Pengirim telah diterima dan disetujui Penerima.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 20 ayat (2)",
    "isi": "Persetujuan atas penawaran Transaksi Elektronik sebagaimana dimaksud pada ayat (1) harus dilakukan dengan pernyataan penerimaan secara elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "pasal": "Pasal 21",
    "ayat": "Pasal 21 ayat (1)",
    "isi_pokok": "Pengirim atau Penerima dapat melakukan Transaksi Elektronik sendiri, melalui pihak yang dikuasakan olehnya, atau melalui Agen Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 21 ayat (2)",
    "isi": "Pihak yang bertanggung jawab atas segala akibat hukum dalam pelaksanaan Transaksi Elektronik sebagaimana dimaksud pada ayat (1) diatur sebagai berikut:\na. jika dilakukan sendiri, segala akibat hukum dalam pelaksanaan Transaksi Elektronik menjadi tanggung jawab para pihak yang bertransaksi;\nb. jika dilakukan melalui pemberian kuasa, segala akibat hukum dalam pelaksanaan Transaksi Elektronik menjadi tanggung jawab pemberi kuasa; atau\nc. jika dilakukan melalui Agen Elektronik, segala akibat hukum dalam pelaksanaan Transaksi Elektronik menjadi tanggung jawab penyelenggara Agen Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 21 ayat (3)",
    "perbuatan_hukum": "bertanggung jawab atas segala akibat hukum dalam pelaksanaan Transaksi Elektronik",
    "detail_ketentuan": "bertanggung jawab atas segala akibat hukum dalam pelaksanaan Transaksi Elektronik",
    "regulasi": "UU_11_2008"
  },
  {
    "ayat": "Pasal 21 ayat (3)",
    "perbuatan_hukum": "bertanggung jawab atas akibat hukum jika kerugian Transaksi Elektronik disebabkan gagal beroperasinya Agen Elektronik akibat tindakan pihak ketiga",
    "detail_ketentuan": "bertanggung jawab atas akibat hukum jika kerugian Transaksi Elektronik disebabkan gagal beroperasinya Agen Elektronik akibat tindakan pihak ketiga",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 21 ayat (4)",
    "isi": "Jika kerugian Transaksi Elektronik disebabkan gagal beroperasinya Agen Elektronik akibat kelalaian pihak pengguna jasa layanan, segala akibat hukum menjadi tanggung jawab pengguna jasa layanan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 21 ayat (5)",
    "isi": "Ketentuan sebagaimana dimaksud pada ayat (2) tidak berlaku dalam hal dapat dibuktikan terjadinya keadaan memaksa, kesalahan, dan/atau kelalaian pihak pengguna Sistem Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 22 ayat (1)",
    "isi": "Penyelenggara Agen Elektronik tertentu harus menyediakan fitur pada Agen Elektronik yang dioperasikannya yang memungkinkan penggunanya melakukan perubahan informasi yang masih dalam proses transaksi.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 22 ayat (2)",
    "isi": "Ketentuan lebih lanjut mengenai penyelenggara Agen Elektronik tertentu sebagaimana dimaksud pada ayat (1) diatur dengan Peraturan Pemerintah.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 23 ayat (1)",
    "isi": "Setiap penyelenggara negara, Orang, Badan Usaha, dan/atau masyarakat berhak memiliki Nama Domain berdasarkan prinsip pendaftar pertama.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 23 ayat (2)",
    "isi": "Pemilikan dan penggunaan Nama Domain sebagaimana dimaksud pada ayat (1) harus didasarkan pada iktikad baik, tidak melanggar prinsip persaingan usaha secara sehat, dan tidak melanggar hak Orang lain.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 23 ayat (3)",
    "isi": "Setiap penyelenggara negara, Orang, Badan Usaha, atau masyarakat yang dirugikan karena penggunaan Nama Domain secara tanpa hak oleh Orang lain, berhak mengajukan gugatan pembatalan Nama Domain dimaksud.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 24 ayat (1)",
    "isi": "Pengelola Nama Domain adalah Pemerintah dan/atau masyarakat.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 24 ayat (2)",
    "isi": "Dalam hal terjadi perselisihan pengelolaan Nama Domain oleh masyarakat, Pemerintah berhak mengambil alih sementara pengelolaan Nama Domain yang diperselisihkan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 24 ayat (3)",
    "isi": "Pengelola Nama Domain yang berada di luar wilayah Indonesia dan Nama Domain yang diregistrasinya diakui keberadaannya sepanjang tidak bertentangan dengan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 24 ayat (4)",
    "isi": "Ketentuan lebih lanjut mengenai pengelolaan Nama Domain sebagaimana dimaksud pada ayat (1), ayat (2), dan ayat (3) diatur dengan Peraturan Pemerintah.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 26 ayat (1)",
    "perbuatan": "penggunaan informasi melalui media elektronik yang menyangkut data pribadi seseorang harus dilakukan atas persetujuan Orang yang bersangkutan",
    "detail": "penggunaan informasi melalui media elektronik yang menyangkut data pribadi seseorang harus dilakukan atas persetujuan Orang yang bersangkutan",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 26 ayat (2)",
    "perbuatan": "mengajukan gugatan atas kerugian yang ditimbulkan",
    "detail": "mengajukan gugatan atas kerugian yang ditimbulkan",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 27 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan yang melanggar kesusilaan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 27 ayat (2)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan perjudian.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 27 ayat (3)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan penghinaan dan/atau pencemaran nama baik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 27 ayat (4)",
    "perbuatan": "mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan pemerasan dan/atau pengancaman",
    "detail": "mendistribusikan dan/atau mentransmisikan dan/atau membuat dapat diaksesnya Informasi Elektronik dan/atau Dokumen Elektronik yang memiliki muatan pemerasan dan/atau pengancaman",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 28 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak menyebarkan berita bohong dan menyesatkan yang mengakibatkan kerugian konsumen dalam Transaksi Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 28 ayat (2)",
    "perbuatan": "menyebarkan informasi yang ditujukan untuk menimbulkan rasa kebencian atau permusuhan individu dan/atau kelompok masyarakat tertentu berdasarkan atas suku, agama, ras, dan antargolongan (SARA)",
    "detail": "menyebarkan informasi yang ditujukan untuk menimbulkan rasa kebencian atau permusuhan individu dan/atau kelompok masyarakat tertentu berdasarkan atas suku, agama, ras, dan antargolongan (SARA)",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 30 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum mengakses Komputer dan/atau Sistem Elektronik milik Orang lain dengan cara apa pun.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 30 ayat (2)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum mengakses Komputer dan/atau Sistem Elektronik dengan cara apa pun dengan tujuan untuk memperoleh Informasi Elektronik dan/atau Dokumen Elektronik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 30 ayat (3)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum mengakses Komputer dan/atau Sistem Elektronik dengan cara apa pun dengan melanggar, menerobos, melampaui, atau menjebol sistem pengamanan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 31 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum melakukan intersepsi atau penyadapan atas Informasi Elektronik dan/atau Dokumen Elektronik dalam suatu Komputer dan/atau Sistem Elektronik tertentu milik Orang lain.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "pasal": "Pasal 31",
    "ayat": "Pasal 31 ayat (2)",
    "isi_ayat": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum melakukan intersepsi atas transmisi Informasi Elektronik dan/atau Dokumen Elektronik yang tidak bersifat publik dari, ke, dan di dalam suatu Komputer dan/atau Sistem Elektronik tertentu milik Orang lain, baik yang tidak menyebabkan perubahan apa pun maupun yang menyebabkan adanya perubahan, penghilangan, dan/atau penghentian Informasi Elektronik dan/atau Dokumen Elektronik yang sedang ditransmisikan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 31 ayat (3)",
    "isi": "Kecuali intersepsi sebagaimana dimaksud pada ayat (1) dan ayat (2), intersepsi yang dilakukan dalam rangka penegakan hukum atas permintaan kepolisian, kejaksaan, dan/atau institusi penegak hukum lainnya yang ditetapkan berdasarkan undang-undang.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 31 ayat (4)",
    "isi": "Ketentuan lebih lanjut mengenai tata cara intersepsi sebagaimana dimaksud pada ayat (3) diatur dengan Peraturan Pemerintah.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 32 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum dengan cara apa pun mengubah, menambah, mengurangi, melakukan transmisi, merusak, menghilangkan, memindahkan, menyembunyikan suatu Informasi Elektronik dan/atau Dokumen Elektronik milik Orang lain atau milik publik.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 32 ayat (2)",
    "makna": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum dengan cara apa pun memindahkan atau mentransfer Informasi Elektronik dan/atau Dokumen Elektronik kepada Sistem Elektronik Orang lain yang tidak berhak.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 32 ayat (3)",
    "isi": "Terhadap perbuatan sebagaimana dimaksud pada ayat (1) yang mengakibatkan terbukanya suatu Informasi Elektronik dan/atau Dokumen Elektronik yang bersifat rahasia menjadi dapat diakses oleh publik dengan keutuhan data yang tidak sebagaimana mestinya.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 34 ayat (1)",
    "isi": "Setiap Orang dengan sengaja dan tanpa hak atau melawan hukum memproduksi, menjual, mengadakan untuk digunakan, mengimpor, mendistribusikan, menyediakan, atau memiliki:\na. perangkat keras atau perangkat lunak Komputer yang dirancang atau secara khusus dikembangkan untuk memfasilitasi perbuatan sebagaimana dimaksud dalam Pasal 27 sampai dengan Pasal 33;\nb. sandi lewat Komputer, Kode Akses, atau hal yang sejenis dengan itu yang ditujukan agar Sistem Elektronik menjadi dapat diakses dengan tujuan memfasilitasi perbuatan sebagaimana dimaksud dalam Pasal 27 sampai dengan Pasal 33.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "pasal": "Pasal 34",
    "ayat": "Pasal 34 ayat (2)",
    "isi_ayat": "Tindakan sebagaimana dimaksud pada ayat (1) bukan tindak pidana jika ditujukan untuk melakukan kegiatan penelitian, pengujian Sistem Elektronik, untuk perlindungan Sistem Elektronik itu sendiri secara sah dan tidak melawan hukum.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 38 ayat (1)",
    "perbuatan": "mengajukan gugatan terhadap pihak yang menyelenggarakan Sistem Elektronik dan/atau menggunakan Teknologi Informasi yang menimbulkan kerugian",
    "detail": "mengajukan gugatan terhadap pihak yang menyelenggarakan Sistem Elektronik dan/atau menggunakan Teknologi Informasi yang menimbulkan kerugian",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 38 ayat (2)",
    "isi": "Masyarakat dapat mengajukan gugatan secara perwakilan terhadap pihak yang menyelenggarakan Sistem Elektronik dan/atau menggunakan Teknologi Informasi yang berakibat merugikan masyarakat, sesuai dengan ketentuan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 39 ayat (1)",
    "isi": "Gugatan perdata dilakukan sesuai dengan ketentuan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 39 ayat (2)",
    "isi": "Selain penyelesaian gugatan perdata sebagaimana dimaksud pada ayat (1), para pihak dapat menyelesaikan sengketa melalui arbitrase, atau lembaga penyelesaian sengketa alternatif lainnya sesuai dengan ketentuan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (1)",
    "isi": "Pemerintah memfasilitasi pemanfaatan Teknologi Informasi dan Transaksi Elektronik sesuai dengan ketentuan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (2)",
    "isi": "Pemerintah melindungi kepentingan umum dari segala jenis gangguan sebagai akibat penyalahgunaan Informasi Elektronik dan Transaksi Elektronik yang mengganggu ketertiban umum, sesuai dengan ketentuan Peraturan Perundang-undangan.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (3)",
    "isi": "Pemerintah menetapkan instansi atau institusi yang memiliki data elektronik strategis yang wajib dilindungi.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (4)",
    "isi": "Instansi atau institusi sebagaimana dimaksud pada ayat (3) harus membuat Dokumen Elektronik dan rekam cadang elektroniknya serta menghubungkannya ke pusat data tertentu untuk kepentingan pengamanan data.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (5)",
    "isi": "Instansi atau institusi lain selain diatur pada ayat (3) membuat Dokumen Elektronik dan rekam cadang elektroniknya sesuai dengan keperluan perlindungan data yang dimilikinya.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 40 ayat (6)",
    "perbuatan": "Ketentuan lebih lanjut mengenai peran Pemerintah diatur dengan Peraturan Pemerintah",
    "detail": "Ketentuan lebih lanjut mengenai peran Pemerintah diatur dengan Peraturan Pemerintah",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "pasal": "Pasal 41",
    "ayat": "Pasal 41 ayat (1)",
    "isi": "Masyarakat dapat berperan meningkatkan pemanfaatan Teknologi Informasi melalui penggunaan dan Penyelenggaraan Sistem Elektronik dan Transaksi Elektronik sesuai dengan ketentuan Undang-Undang ini.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 41 ayat (2)",
    "isi": "Peran masyarakat sebagaimana dimaksud pada ayat (1) dapat diselenggarakan melalui lembaga yang dibentuk oleh masyarakat.",
    "regulasi": "UU_11_2008"
  }
]

[
  {
    "ayat": "Pasal 41 ayat (3)",
    "isi": "Lembaga sebagaimana dimaksud pada ayat (2) dapat memiliki fungsi konsultasi dan mediasi.",
    "regulasi": "UU_11_2008"
  }
]

[
